            if (name !== undefined && name !== "") {
                return { serviceAccount: { __kind: "serviceAccount", appRefName: owner.appLabel, name } };
            }
            ctx.diagnostics.push(`${where}: service_account_id references data.elementum_service_account.${dataLabel}, but the stream has no matching named data block; dropped`);
            return undefined;
